// Node: Build Requests (v23, sebelumnya Code in JavaScript1)
// Posisi: Get Listings -> Get Rate History -> [node ini] -> Is Booking (AI Path)?
// Mode: Run Once for All Items
//
// Output: 1 item per (listing, target_date). extraction_path menentukan jalur:
//   'ai'       MrScraper Extract Structured Data, loop per halaman (Booking)
//   'markdown' MrScraper Fetch Rendered HTML + Gemini, loop 5 halaman (Tiket)
// Listing dibaca dari node Get Listings. Input node ini = baris Rate_History (Get Rate History), tidak dipakai di sini.

// Target menginap: Jumat dan Sabtu terdekat (weekday Luxon: 5 = Jumat, 6 = Sabtu).
// Naikkan WEEKEND_COUNT untuk weekend berikutnya. Tiap tanggal = 1 call per listing.
const WEEKEND_COUNT = 2; // 2 weekend = 4 tanggal (Jumat, Sabtu x 2). Perbandingan antar tanggal langsung ada di 1 run
const WEEKEND_CHECKIN_DAYS = [5, 6];
const SEARCH_HORIZON_DAYS = 60;

const weekendOffsets = () => {
  const offsets = [];
  const needed = WEEKEND_COUNT * WEEKEND_CHECKIN_DAYS.length;
  for (let day = 1; offsets.length < needed && day <= SEARCH_HORIZON_DAYS; day++) {
    if (WEEKEND_CHECKIN_DAYS.includes($today.plus({ days: day }).weekday)) {
      offsets.push(day);
    }
  }
  return offsets;
};

const DAY_OFFSETS = weekendOffsets();
const NIGHTS = 1;
const ISO_DATE = 'yyyy-MM-dd';
const TRAVELOKA_DATE = 'dd-MM-yyyy';

// URL dan URLSearchParams tidak tersedia di sandbox Code node n8n 2.x. Pakai encodeURIComponent (ECMAScript).
const toQueryString = (params) => Object.entries(params)
  .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(String(value))}`)
  .join('&');

const appendQuery = (baseUrl, params) => {
  const separator = baseUrl.includes('?') ? '&' : '?';
  return `${baseUrl}${separator}${toQueryString(params)}`;
};

const LOCALE_SUFFIX = /\.[a-z]{2}(-[a-z]{2})?\.html$/i;

// house-sangkuriang.id.html?aid=...&sid=... -> house-sangkuriang.en-gb.html
const toBookingBase = (url) => String(url).split('#')[0].split('?')[0].replace(LOCALE_SUFFIX, '.en-gb.html');

// Strategy: 1 builder per platform. Format param tiap platform sesuai hasil test di handover v3.
const DETAIL_URL_BUILDERS = {
  // Buang parameter sesi (aid, label, sid, srepoch) dan kunci bahasa + mata uang.
  // Tanpa ini, Booking mengembalikan USD atau CAD dan nama kamar berganti bahasa tiap run.
  'booking.com': (url, stay) => appendQuery(toBookingBase(url), {
    selected_currency: 'IDR',
    group_adults: 2,
    no_rooms: 1,
    group_children: 0,
    checkin: stay.checkin.toFormat(ISO_DATE),
    checkout: stay.checkout.toFormat(ISO_DATE),
  }),
  'agoda.com': (url, stay) => appendQuery(url, {
    checkIn: stay.checkin.toFormat(ISO_DATE),
    checkOut: stay.checkout.toFormat(ISO_DATE),
    currency: 'IDR',
    currencyCode: 'IDR',
    priceCur: 'IDR',
    rooms: 1,
    adults: 2,
    childs: 0,
    los: NIGHTS,
  }),
  'traveloka.com': (url, stay) => url
    .replace('{{checkin}}', stay.checkin.toFormat(TRAVELOKA_DATE))
    .replace('{{checkout}}', stay.checkout.toFormat(TRAVELOKA_DATE)),
  'tiket.com': (url, stay) => appendQuery(url, {
    checkin: stay.checkin.toFormat(ISO_DATE),
    checkout: stay.checkout.toFormat(ISO_DATE),
    adult: 2,
    room: 1,
    night: NIGHTS,
  }),
};

// Jalur ekstraksi per platform. Satu-satunya tempat mengatur platform aktif.
//   'ai'       MrScraper Extract Structured Data, cabang true di Is Booking (AI Path)?
//   'markdown' MrScraper Fetch Rendered HTML + Gemini, cabang false
// Platform yang tidak tercantum TIDAK discrape dan tidak dihitung di Check Data Quality.
// Kalau endpoint AI MrScraper sedang kosong (empty_response), ubah 'booking.com' ke 'markdown'.
const EXTRACTION_PATH = {
  'booking.com': 'ai',
  // 'agoda.com': 'markdown', // nonaktif v21: 0 harga di semua run 100 sampai 109. Dugaan: harga dimuat JavaScript.
  //                         Tetap memakai 20 request Fetch + kuota Gemini per run, dan ikut memicu 429 MrScraper (run 109).
  'tiket.com': 'markdown',
  // 'traveloka.com': 'markdown', // nonaktif: markdown selalu tanpa harga (2 token per halaman, halaman kosong)
};

const platformKey = (listing) => String(listing.platform ?? '').trim().toLowerCase();
const isEnabled = (listing) => Boolean(EXTRACTION_PATH[platformKey(listing)]);

const resolveBuilder = (listing) => {
  const platform = String(listing.platform ?? '').trim().toLowerCase();
  const builder = DETAIL_URL_BUILDERS[platform];
  if (!builder) {
    throw new Error(`Platform tidak dikenal di ${listing.listing_id}: "${listing.platform}"`);
  }
  return builder;
};

const toStay = (dayOffset) => {
  const checkin = $today.plus({ days: dayOffset });
  return { checkin, checkout: checkin.plus({ days: NIGHTS }) };
};

return $('Get Listings').all().filter(({ json: listing }) => isEnabled(listing)).flatMap(({ json: listing }) => {
  const buildUrl = resolveBuilder(listing);
  return DAY_OFFSETS.map((dayOffset) => {
    const stay = toStay(dayOffset);
    return {
      json: {
        ...listing,
        target_date: stay.checkin.toFormat(ISO_DATE),
        url: buildUrl(listing.url, stay),
        extraction_path: EXTRACTION_PATH[platformKey(listing)],
      },
    };
  });
});

// Node: Normalize Booking Rates (v23, gabungan Normalize Scrap Result + Calculate Delta)
// Posisi: MrScraper Extract Booking -> [node ini] -> Loop Booking Pages (kembali ke loop)
// Mode: Run Once for All Items. Jalan 1 kali per halaman Booking (batch loop = 1).
//
// Output: 1 item per rate (room type x opsi harga), lengkap dengan pembanding histori.
// Minimal 1 item per halaman. Loop selalu menerima item dari 1 jalur yang sama, termasuk saat MrScraper error.
// Baris TIDAK ditulis di sini. Semua baris ditulis sekali setelah Merge Rates.

const LOOP_NODE = 'Loop Booking Pages';
const URL_BUILDER_NODE = 'Build Requests';

const EXTRACTION_STATUS = {
  OK: 'ok',                       // room type dan harga terbaca
  WRONG_CURRENCY: 'wrong_currency', // harga terbaca tapi bukan IDR
  NO_PRICES: 'no_prices',         // room type terbaca, harga kosong (kemungkinan sold out asli)
  NO_ROOM_TYPES: 'no_room_types', // halaman terbaca, tanpa room_types
  EMPTY_RESPONSE: 'empty_response', // MrScraper: status Finished, tokenUsage 0, data kosong
  SCRAPE_ERROR: 'scrape_error',     // MrScraper mengisi field error
};

// "Rp 605,455 for 1 night; tax excluded" -> 605455. Ambil kelompok angka PERTAMA saja,
// supaya angka lain di kalimat (jumlah malam, persen pajak) tidak ikut menempel.
const parsePrice = (value) => {
  const match = String(value ?? '').match(/\d[\d.,]*/);
  if (!match) {
    return null;
  }
  // Buang desimal 1-2 digit di ujung ("Rp 412.752,00" -> 412752), lalu buang pemisah ribuan
  const digits = match[0].replace(/[.,]\d{1,2}$/, '').replace(/\D/g, '');
  return digits ? Number.parseInt(digits, 10) : null;
};

// Harga wajib IDR. Tolak hanya kalau ada penanda mata uang lain.
// Angka tanpa simbol diterima, karena Tiket/Traveloka/Agoda sudah dikunci IDR lewat URL.
const FOREIGN_CURRENCY = /\$|usd|cad|eur|€|sgd|myr|aud|gbp|£|jpy|¥/i;
const isRupiah = (value) => !FOREIGN_CURRENCY.test(String(value ?? ''));


// Booking kadang menampilkan harga sebelum pajak, kadang termasuk pajak. Basis dicatat di rate_key,
// mesin pembanding menormalisasi basis sebelum membandingkan harga.
const priceBasisOf = (rate) => {
  const text = `${rate.price_total ?? ''} ${rate.price_breakdown ?? ''}`.toLowerCase();
  if (/exclud|belum termasuk|before tax|sebelum pajak/.test(text)) return 'excl';
  if (/includ|termasuk pajak|incl\./.test(text)) return 'incl';
  return 'unknown';
};

const hostAndPath = (url) => String(url ?? '').split('?')[0].split('//')[1] ?? '';

// MrScraper Extract Booking memakai On Error: Continue (regular output).
// Item gagal berisi { error } tanpa data -> scrape_error. Item tetap lewat jalur yang sama, loop tidak putus.
const scrape = $input.first().json;

// Utama: paired item ke item loop saat ini (batch size 1).
// Cadangan: cocokkan URL. Exact match dulu, lalu host+path. Hanya dipakai kalau hasilnya tepat 1.
const findUniqueRequest = (predicate) => {
  const candidates = $(URL_BUILDER_NODE).all().map((item) => item.json).filter(predicate);
  return candidates.length === 1 ? candidates[0] : null;
};

const findRequest = () => {
  try {
    return $(LOOP_NODE).itemMatching(0).json;
  } catch (pairingError) {
    const scrapedUrl = String(scrape.data?.url ?? scrape.url ?? '');
    const scrapedPath = hostAndPath(scrapedUrl);
    const request = findUniqueRequest((candidate) => candidate.url === scrapedUrl)
      ?? findUniqueRequest((candidate) => scrapedPath !== '' && scrapedPath === hostAndPath(candidate.url));
    if (!request) {
      throw new Error(`Request loop tidak bisa dilacak untuk URL ${scrapedUrl}. Detail: ${pairingError.message}`);
    }
    return request;
  }
};

const request = findRequest();

const baseRow = {
  listing_id: request.listing_id,
  nama_properti: request.nama_properti,
  platform: request.platform,
  target_date: request.target_date,
};

const toRateRow = (roomName, rate) => {
  const rupiah = isRupiah(rate.price_total);
  const price = rupiah ? parsePrice(rate.price_total) : null;
  return {
    ...baseRow,
    room_type: roomName,
    price,
    availability_status: price === null ? 'unknown' : 'available',
    breakfast_included: Boolean(rate.breakfast_included),
    cancellation_policy: rate.cancellation_policy || 'not_available',
    price_basis: priceBasisOf(rate),
    extraction_status: rupiah ? EXTRACTION_STATUS.OK : EXTRACTION_STATUS.WRONG_CURRENCY,
  };
};

const toUnavailableRow = (roomName, extractionStatus) => ({
  ...baseRow,
  room_type: roomName,
  price: null,
  // sold_out HANYA kalau halaman terbaca dan kamar tampil tanpa harga (no_prices).
  // Status lain = kegagalan scraping, bukan kamar habis.
  availability_status: extractionStatus === EXTRACTION_STATUS.NO_PRICES ? 'sold_out' : 'unknown',
  breakfast_included: false,
  cancellation_policy: 'not_available',
  extraction_status: extractionStatus,
});

const roomTypes = scrape.data?.data?.room_types ?? [];

// Pola 22-24 Sep dan 30 Sep: MrScraper membalas sukses tapi tidak membaca halaman (tokenUsage 0).
const diagnoseEmpty = (result) => {
  if (!result || result.error) return EXTRACTION_STATUS.SCRAPE_ERROR;
  if (Number(result.tokenUsage) === 0) return EXTRACTION_STATUS.EMPTY_RESPONSE;
  return EXTRACTION_STATUS.NO_ROOM_TYPES;
};

// Minimal 1 baris per halaman, supaya halaman gagal tetap tercatat di Rate_History
const normalizedRows = roomTypes.length === 0
  ? [toUnavailableRow('No room type returned', diagnoseEmpty(scrape.data))]
  : roomTypes.flatMap((room) => {
    const roomName = room.name || 'Unknown room type';
    const rates = room.prices ?? [];
    return rates.length === 0
      ? [toUnavailableRow(roomName, EXTRACTION_STATUS.NO_PRICES)]
      : rates.map((rate) => toRateRow(roomName, rate));
  });

// ===== MESIN PEMBANDING (SALIN IDENTIK di Normalize Booking Rates dan Normalize Markdown Rates) =====
// Code node tidak bisa berbagi modul. Ubah aturan alert di KEDUA node.
//
// Aturan alert: alert = LEVEL harga baru yang terkonfirmasi di 2 scan berturut-turut, berbeda >= 5%
// dari level lama. Alasan: MrScraper AI mengambil rate plan berbeda antar scan. Contoh Girava 09 Oct:
// 869.760, 1.234.691, 869.760 (3 scan). Satu scan yang menyimpang hanya menjadi kandidat.
// Konsekuensi: alert muncul 1 scan setelah perubahan pertama terlihat.
// Kunci pembanding: listing|tanggal|kamar kanonik|sarapan. Basis pajak tidak masuk kunci karena
// harga dinormalisasi ke excl. rate_key yang ditulis ke sheet tetap format lama (nama asli + basis).

const HISTORY_NODE = 'Get Rate History';
const ALERT_THRESHOLD_PCT = 5;  // selisih level lama ke level baru
const SAME_LEVEL_PCT = 2.5;     // selisih sekecil ini = level sama. Fluktuasi Tiket antar scan sampai 2,4%

// Harga incl = excl x 1,0901. Bukti: 60 dari 71 pergantian basis Booking (run 100 sampai 109) cocok faktor ini.
// Teks "10% tax" dari MrScraper tidak dipakai karena tidak cocok dengan data.
// unknown diperlakukan incl: 28 dari 35 kasus unknown setara harga incl.
const INCL_TAX_FACTOR = 1.0901;
const BASIS_FACTOR = { excl: 1, incl: INCL_TAX_FACTOR, unknown: INCL_TAX_FACTOR };

const normalizeKeyPart = (value) => String(value ?? '').trim().toLowerCase();

// 1 definisi key untuk tulis dan baca. Tidak bergantung ke format tanggal/boolean di Sheets.
const buildRateKey = (row) => [
  row.listing_id,
  row.target_date,
  row.room_type,
  row.breakfast_included,
  row.price_basis ?? 'unknown',
].map(normalizeKeyPart).join('|');

// Kata yang tidak membedakan tipe kamar. Token diurutkan supaya urutan kata tidak berpengaruh.
// "Deluxe Room Twin Bed" dan "Deluxe Twin Room" -> "deluxe twin".
// SALIN IDENTIK di Calculate Delta, Calculate Delta Batch, dan Enrich Report (Code node tidak bisa berbagi modul).
const ROOM_FILLER_WORDS = new Set(['room', 'rooms', 'kamar', 'bed', 'beds', 'with', 'dengan', 'the', 'a', 'and', 'dan']);
const canonicalRoom = (name) => (String(name ?? '').toLowerCase().match(/[a-z0-9]+/g) ?? [])
  .filter((token) => !ROOM_FILLER_WORDS.has(token))
  .sort()
  .join(' ');

const toCompareKey = (rateKey) => {
  const [listing, date, room, breakfast] = String(rateKey).split('|');
  return [listing, date, canonicalRoom(room), breakfast].join('|');
};
const basisOf = (rateKey) => String(rateKey).split('|')[4] || 'unknown';
const factorOf = (basis) => BASIS_FACTOR[basis] ?? INCL_TAX_FACTOR;
const toExcl = (price, basis) => price / factorOf(basis);
const fromExcl = (priceExcl, basis) => Math.round(priceExcl * factorOf(basis));

// Harga selalu integer IDR. Buang semua non-digit supaya aman dari format "500.000" atau "500,000".
const toPrice = (value) => {
  const match = String(value ?? '').match(/\d[\d.,]*/);
  if (!match) {
    return null;
  }
  const digits = match[0].replace(/[.,]\d{1,2}$/, '').replace(/\D/g, '');
  return digits ? Number(digits) : null;
};

const pctChange = (current, reference) => Math.round(((current - reference) / reference) * 1000) / 10;
const isSameLevel = (price, level) => Math.abs(pctChange(price, level)) <= SAME_LEVEL_PCT;
const byNewestFirst = (a, b) => new Date(b.timestamp) - new Date(a.timestamp);

// ---------- histori ----------
// Pengaman: baris dengan run_id run ini bukan histori
const currentRunId = (() => {
  try {
    return String($execution.id);
  } catch (notAvailable) {
    return '';
  }
})();

const historyRows = $(HISTORY_NODE).all()
  .map((item) => item.json)
  .filter((row) => row.rate_key && String(row.run_id) !== currentRunId);

// Urutan run menurut waktu baris pertama
const runStartedAt = historyRows.reduce((index, row) => {
  const time = new Date(row.timestamp).getTime();
  return index.set(row.run_id, Math.min(index.get(row.run_id) ?? Infinity, time));
}, new Map());

// compareKey -> Map(run_id -> observasi termurah di run itu). Satu observasi per scan.
// Observasi = { excl, price, basis }. Harga asli disimpan supaya previous_price tidak bergeser karena pembulatan.
const observationsByKey = historyRows.reduce((index, row) => {
  const price = toPrice(row.price);
  if (price === null) {
    return index;
  }
  const key = toCompareKey(row.rate_key);
  const perRun = index.get(key) ?? new Map();
  const basis = basisOf(row.rate_key);
  const observation = { excl: toExcl(price, basis), price, basis };
  const cheapest = perRun.get(row.run_id);
  if (!cheapest || observation.excl < cheapest.excl) {
    perRun.set(row.run_id, observation);
  }
  return index.set(key, perRun);
}, new Map());

const seriesOf = (key) => [...(observationsByKey.get(key) ?? new Map())]
  .sort(([runA], [runB]) => runStartedAt.get(runA) - runStartedAt.get(runB))
  .map(([, observation]) => observation);

// Baris terbaru per rate_key persis. Dipakai untuk baris yang bukan termurah di kuncinya.
const latestByRateKey = [...historyRows]
  .sort(byNewestFirst)
  .reduce((index, row) => (index.has(row.rate_key) ? index : index.set(row.rate_key, row)), new Map());

// Status terakhir yang diketahui per kunci pembanding (available, sold_out)
const lastKnownStatus = [...historyRows]
  .sort(byNewestFirst)
  .filter((row) => normalizeKeyPart(row.availability_status) !== 'unknown')
  .reduce((index, row) => {
    const key = toCompareKey(row.rate_key);
    return index.has(key) ? index : index.set(key, normalizeKeyPart(row.availability_status));
  }, new Map());

// Stay dianggap sudah dipantau hanya kalau halamannya pernah TERBACA (bukan fetch_failed, empty_response, dst)
const READ_STATUSES = new Set(['ok', 'no_prices', 'wrong_currency', 'sold_out_notice']);
const stayOf = (rateKey) => String(rateKey).split('|').slice(0, 2).join('|');
const seenStays = new Set(historyRows
  .filter((row) => READ_STATUSES.has(normalizeKeyPart(row.extraction_status)))
  .map((row) => stayOf(row.rate_key)));
const seenKeys = new Set(historyRows.map((row) => toCompareKey(row.rate_key)));

// ---------- level harga ----------
// Level terkonfirmasi = harga yang muncul di 2 scan berturut-turut (selisih <= SAME_LEVEL_PCT).
// Harga yang beda dari level hanya menjadi kandidat sampai scan berikutnya mengulanginya.
// Level menyimpan harga asli terakhir per basis. Contoh Dago 207: 293.554 (excl) dan 320.000 (incl) = level sama.
const toLevel = (observation, previousLevel = null) => ({
  excl: observation.excl,
  priceByBasis: { ...(previousLevel?.priceByBasis ?? {}), [observation.basis]: observation.price },
});

const replayLevels = (series) => series.reduce(({ confirmed, candidate }, observation) => {
  if (confirmed !== null && isSameLevel(observation.excl, confirmed.excl)) {
    return { confirmed: toLevel(observation, confirmed), candidate: null };
  }
  if (candidate !== null && isSameLevel(observation.excl, candidate.excl)) {
    return { confirmed: toLevel(observation, toLevel(candidate)), candidate: null };
  }
  return { confirmed, candidate: observation };
}, { confirmed: null, candidate: null });

// reference = observasi pembanding. levelChanged = scan ini mengonfirmasi level baru.
const assessLevel = (series, priceExcl) => {
  const { confirmed, candidate } = replayLevels(series);
  if (confirmed !== null && isSameLevel(priceExcl, confirmed.excl)) {
    return { reference: confirmed, levelChanged: false };
  }
  if (candidate !== null && isSameLevel(priceExcl, candidate.excl)) {
    // Tanpa level lama (stay baru dipantau) = konfirmasi level pertama, bukan perubahan
    return { reference: confirmed ?? candidate, levelChanged: confirmed !== null };
  }
  return { reference: confirmed ?? candidate, levelChanged: false };
};

// previous_price ditulis dalam basis baris ini supaya setara dengan price.
// Pakai harga asli kalau level pernah teramati di basis yang sama, konversi faktor kalau belum.
const referencePriceIn = (reference, basis) => reference.priceByBasis?.[basis]
  ?? (reference.basis === basis ? reference.price : fromExcl(reference.excl, basis));

// ---------- run ini ----------
// Satu tipe kamar bisa punya beberapa opsi harga dengan status sarapan sama (beda okupansi atau promo).
// Ambil harga termurah per rate_key, sama seperti v21.
const isCheaper = (candidate, current) => {
  const candidatePrice = toPrice(candidate.price);
  const currentPrice = toPrice(current.price);
  if (candidatePrice === null) return false;
  return currentPrice === null || candidatePrice < currentPrice;
};

const cheapestPerRateKey = (rows) => [...rows
  .reduce((index, row) => {
    const key = buildRateKey(row);
    const current = index.get(key);
    return !current || isCheaper(row, current) ? index.set(key, row) : index;
  }, new Map())
  .values()];

// ---------- pembanding ----------
// Input: baris ternormalisasi (1 item per rate). Output: baris + rate_key, previous_price, delta_pct,
// is_new, status_changed, is_alert. Semua baris dikembalikan, termasuk baris gagal (untuk diagnosis).
const compareWithHistory = (normalizedRows) => {
  const currentRows = cheapestPerRateKey(normalizedRows)
    .map((row) => {
      const rateKey = buildRateKey(row);
      const price = toPrice(row.price);
      const basis = basisOf(rateKey);
      return { row, rateKey, compareKey: toCompareKey(rateKey), basis, price, priceExcl: price === null ? null : toExcl(price, basis) };
    });

  // Baris termurah per kunci pembanding = wakil kunci itu di scan ini. Hanya wakil yang bisa memicu alert.
  const leadByKey = currentRows
    .filter((entry) => entry.priceExcl !== null)
    .reduce((index, entry) => {
      const lead = index.get(entry.compareKey);
      return !lead || entry.priceExcl < lead.priceExcl ? index.set(entry.compareKey, entry) : index;
    }, new Map());

  const statusChangedOf = (entry) => {
    const current = normalizeKeyPart(entry.row.availability_status);
    const previous = lastKnownStatus.get(entry.compareKey);
    return current !== 'unknown' && previous !== undefined && current !== previous;
  };

  const evaluate = (entry) => {
    const base = {
      ...entry.row,
      rate_key: entry.rateKey,
      is_new: !seenKeys.has(entry.compareKey) && seenStays.has(stayOf(entry.rateKey)),
      status_changed: statusChangedOf(entry),
      is_alert: false,
    };

    if (entry.priceExcl === null) {
      return { ...base, previous_price: null, delta_pct: null };
    }

    if (leadByKey.get(entry.compareKey) === entry) {
      const series = seriesOf(entry.compareKey);
      const { reference, levelChanged } = assessLevel(series, entry.priceExcl);
      if (reference === null) {
        return { ...base, previous_price: null, delta_pct: null };
      }
      const deltaPct = pctChange(entry.priceExcl, reference.excl);
      return {
        ...base,
        previous_price: referencePriceIn(reference, entry.basis),
        delta_pct: deltaPct,
        is_alert: levelChanged && Math.abs(deltaPct) >= ALERT_THRESHOLD_PCT,
      };
    }

    // Opsi lebih mahal dengan kunci sama: pembanding = rate_key persis, hanya informasi
    const previousPrice = toPrice(latestByRateKey.get(entry.rateKey)?.price);
    return {
      ...base,
      previous_price: previousPrice,
      delta_pct: previousPrice ? pctChange(entry.price, previousPrice) : null,
    };
  };

  return currentRows.map(evaluate);
};

return compareWithHistory(normalizedRows).map((json) => ({ json }));

// Node: Build Area Scan URL
// Mode: Run Once for All Items
// en-gb + selected_currency=IDR: mengunci bahasa dan mata uang, sama dengan cabang 1.
const AREA_CITY = 'Bandung'; // kota untuk pencarian Booking.com, prompt Listing Agent, dan header Telegram
const DAY_OFFSET = 7;
const ISO_DATE = 'yyyy-MM-dd';

const checkin = $today.plus({ days: DAY_OFFSET });
const checkout = checkin.plus({ days: 1 });

const url = 'https://www.booking.com/searchresults.en-gb.html'
  + `?ss=${encodeURIComponent(AREA_CITY)}&selected_currency=IDR&checkin=${checkin.toFormat(ISO_DATE)}`
  + `&checkout=${checkout.toFormat(ISO_DATE)}&group_adults=2&no_rooms=1&group_children=0`;

return [{ json: { area_city: AREA_CITY, area_scan_url: url } }];

// Node: Normalize Area Listing (v23, sebelumnya Normalize Scrap Result1)
// Posisi: MrScraper Extract Listing -> [node ini] -> Loop Area Listings (kembali ke loop)
// Mode: Run Once for All Items. Jalan 1 kali per listing (batch loop = 1).
// Output: 1 baris per properti, harga = rate termurah. Nama field sama dengan header Area_Scan.
// MrScraper Extract Listing memakai On Error: Continue (regular output). Kalau detail gagal,
// harga diambil dari halaman pencarian (Listing Agent), jadi loop tetap menerima 1 item.

const LOOP_NODE = 'Loop Area Listings';
const PLATFORM = 'booking.com'; // sama dengan target Build Area Scan URL

// "Rp 605,455 for 1 night" -> 605455. Kelompok angka PERTAMA saja, desimal di ujung dibuang.
const parsePrice = (value) => {
  const match = String(value ?? '').match(/\d[\d.,]*/);
  if (!match) {
    return null;
  }
  const digits = match[0].replace(/[.,]\d{1,2}$/, '').replace(/\D/g, '');
  return digits ? Number.parseInt(digits, 10) : null;
};

// Batch size 1: item loop saat ini. itemMatching untuk mode All Items, .item sebagai cadangan.
const readLoopItem = () => {
  try {
    return $(LOOP_NODE).itemMatching(0).json;
  } catch (pairingError) {
    return $(LOOP_NODE).item.json;
  }
};

const listing = readLoopItem();
const scrape = $input.first().json;
const hotel = scrape.data?.data ?? {};
const roomTypes = Array.isArray(hotel.room_types) ? hotel.room_types : [];

const prices = roomTypes
  .flatMap((room) => (room.prices ?? []).map((rate) => parsePrice(rate.price_total)))
  .filter((price) => price !== null && price > 0);

return [{
  json: {
    scan_date: $today.toFormat('yyyy-MM-dd'),
    platform: PLATFORM,
    nama_properti: listing.name || hotel.name || 'Unknown',
    price_per_night: prices.length ? Math.min(...prices) : parsePrice(listing.price_per_night),
    rating: listing.rating ?? null,
    detail_url: listing.detail_url,
  },
}];

// Node: Split Listings (cabang Area, v23)
// Posisi: MrScraper Listing Agent -> [node ini] -> Has Listings?
// Mode: Run Once for All Items
//
// Output: 1 item per listing (has_listing true), maksimal MAX_DETAIL_SCRAPES.
// Kalau tidak ada listing valid: 1 item penanda (has_listing false) berisi alasan. Tidak melempar error,
// supaya laporan Telegram tetap terkirim dengan alasan yang jelas.
// Contoh 1 Oct 2026: Listing Agent membalas Finished, data [], reason "No complete hotel or villa listings were found in the HTML."

const MAX_DETAIL_SCRAPES = 5; // 1 listing = 1 call Extract structured Data1

const NAME_KEYS = ['name', 'hotel_name', 'property_name', 'title'];
const URL_KEYS = ['detail_url', 'url', 'link', 'detail_link', 'property_url'];
const PRICE_KEYS = ['price_per_night', 'price', 'price_total', 'nightly_price'];

const firstValue = (listing, keys) => keys.map((key) => listing?.[key]).find((value) => value);

const isListingArray = (value) => Array.isArray(value)
  && value.some((entry) => entry && typeof entry === 'object' && firstValue(entry, NAME_KEYS));

// Listing Agent membungkus hasil berbeda-beda, contoh data.data.response.data.
// Telusuri objek sampai ketemu array yang berisi listing.
const findListings = (node, depth = 0) => {
  if (depth > 5 || node === null || typeof node !== 'object') {
    return [];
  }
  if (isListingArray(node)) {
    return node;
  }
  for (const value of Object.values(node)) {
    const found = findListings(value, depth + 1);
    if (found.length > 0) {
      return found;
    }
  }
  return [];
};

const toQueryString = (params) => Object.entries(params)
  .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(String(value))}`)
  .join('&');

const readParam = (url, name) => {
  const match = String(url).match(new RegExp(`[?&]${name}=([^&#]+)`));
  return match ? decodeURIComponent(match[1]) : null;
};

// URL dari halaman search membawa parameter sesi dan tanpa mata uang.
// Samakan dengan cabang 1: en-gb + IDR, tanggal diambil dari URL asli.
const cleanBookingUrl = (url) => {
  const base = String(url).split('#')[0].split('?')[0]
    .replace(/(\.[a-z]{2}(-[a-z]{2})?)?\.html$/i, '.en-gb.html');
  return `${base}?${toQueryString({
    selected_currency: 'IDR',
    group_adults: 2,
    no_rooms: 1,
    group_children: 0,
    checkin: readParam(url, 'checkin') ?? '',
    checkout: readParam(url, 'checkout') ?? '',
  })}`;
};

// MrScraper Listing Agent memakai On Error: Continue (regular output). Item gagal berisi { error }.
const result = $input.first()?.json ?? {};
const payload = result.data ?? {};

const listings = findListings(payload)
  .map((listing) => ({
    name: String(firstValue(listing, NAME_KEYS) ?? '').replace(/\s*opens in new window\s*$/i, '').trim(),
    detail_url: firstValue(listing, URL_KEYS),
    price_per_night: firstValue(listing, PRICE_KEYS) ?? null,
    rating: listing.rating ?? null,
  }))
  .filter((listing) => listing.name && listing.detail_url)
  .slice(0, MAX_DETAIL_SCRAPES);

// Alasan dari MrScraper (data.data.response.reason), pesan error node, atau status job
const noListingReason = () => {
  const errorMessage = typeof result.error === 'object' ? result.error?.message : result.error;
  const reason = payload.data?.response?.reason ?? payload.data?.reason ?? errorMessage ?? payload.error;
  return String(reason ?? `status ${payload.status ?? '-'}, tokenUsage ${payload.tokenUsage ?? '-'}, data kosong`).slice(0, 200);
};

if (listings.length === 0) {
  return [{ json: { has_listing: false, no_listing_reason: noListingReason() } }];
}

return listings.map((listing, index) => ({
  json: {
    ...listing,
    has_listing: true,
    detail_url: cleanBookingUrl(listing.detail_url),
    property_rank: index + 1,
  },
}));

// Node: Build Report (v23, gabungan Check Data Quality + Enrich Report)
// Posisi: Upsert Current_Status -> [node ini] -> Has Data Issue?
// Mode: Run Once for All Items
//
// 1. Kesehatan per platform. Platform SEHAT kalau minimal MIN_PRICED_PAGES halaman-nya punya harga.
//    Laporan dibuat dari platform sehat saja. Warning memblok laporan hanya kalau TIDAK ADA platform sehat.
// 2. Bagian report: alerts, market, sold_out, cross_platform, date_comparison, trends. Tanpa request Gemini.

const RATES_NODE = 'Merge Rates';
const REQUEST_NODE = 'Build Requests';
const BATCH_NODE = 'Prepare Gemini Batches';
const HISTORY_NODE = 'Get Rate History';
const MIN_PRICED_PAGES = 1; // harga asli dari halaman, bukan tebakan, jadi 1 halaman sudah layak dipakai
const MAX_ALERTS = 15;
const MAX_SOLD_OUT = 8;
const MIN_STREAK_DAYS = 2;   // tren: minimal 2 perubahan harian searah (3 hari data)
const MAX_TRENDS = 10;

const toPrice = (value) => {
  const match = String(value ?? '').match(/\d[\d.,]*/);
  if (!match) {
    return null;
  }
  const digits = match[0].replace(/[.,]\d{1,2}$/, '').replace(/\D/g, '');
  return digits ? Number(digits) : null;
};

const toNumber = (value) => {
  if (value === null || value === undefined || value === '') {
    return null;
  }
  const parsed = Number(String(value).replace(',', '.'));
  return Number.isFinite(parsed) ? parsed : null;
};

const toBoolean = (value) => String(value).trim().toLowerCase() === 'true';
const platformOf = (row) => String(row.platform ?? '').trim().toLowerCase();
const requestKey = (row) => `${row.listing_id}|${row.target_date}`;
const isFilledRow = (row) => Boolean(row && row.listing_id);
const hasPrice = (row) => toPrice(row.price) !== null;

const countBy = (items, keyOf) => items.reduce((counts, item) => {
  const key = keyOf(item);
  counts[key] = (counts[key] ?? 0) + 1;
  return counts;
}, {});

// Baris run ini langsung dari Merge Rates (data yang sama dengan yang ditulis ke Rate_History).
// Tidak perlu Wait + baca ulang sheet.
const rows = $(RATES_NODE).all().map((item) => item.json).filter(isFilledRow);
const expectedPerPlatform = countBy($(REQUEST_NODE).all().map((item) => item.json), platformOf);

const pricedRequestsPerPlatform = [...new Map(
  rows.filter(hasPrice).map((row) => [requestKey(row), row]),
).values()].reduce((counts, row) => {
  counts[platformOf(row)] = (counts[platformOf(row)] ?? 0) + 1;
  return counts;
}, {});

const platformHealth = Object.entries(expectedPerPlatform).map(([platform, expected]) => {
  const priced = pricedRequestsPerPlatform[platform] ?? 0;
  return { platform, expected, priced, coverage_pct: Math.round((priced / expected) * 100), healthy: priced >= MIN_PRICED_PAGES };
});

// Penyebab halaman tanpa harga, per platform. Contoh: { empty_response: 20 }
const statusCountsOf = (platform) => countBy(
  rows.filter((row) => platformOf(row) === platform && !hasPrice(row)),
  (row) => row.extraction_status || 'unknown',
);
platformHealth.forEach((p) => { p.status_counts = statusCountsOf(p.platform); });

// Pesan error asli dari MrScraper Fetch Markdown, 1 contoh. Node tidak jalan kalau tidak ada platform markdown.
const fetchErrorSample = () => {
  try {
    return ($(BATCH_NODE).first().json.pages ?? []).map((page) => page.fetch_error).find(Boolean) ?? null;
  } catch (notExecuted) {
    return null;
  }
};
const plainText = (text) => String(text).replace(/[<>&]/g, ' ').slice(0, 160);

const healthyPlatforms = new Set(platformHealth.filter((p) => p.healthy).map((p) => p.platform));
const failedPlatforms = platformHealth.filter((p) => !p.healthy);

const buildResult = (warningMessage, report) => [{
  json: { is_data_quality_issue: warningMessage !== null, warning_message: warningMessage, report },
}];

// Teks warning tanpa karakter khusus supaya aman di semua parse mode Telegram
if (healthyPlatforms.size === 0) {
  const describeStatus = (counts) => Object.entries(counts).map(([status, n]) => `${status} ${n}`).join(' ');
  const detail = platformHealth
    .map((p) => `${p.platform} ${p.priced}/${p.expected} (${describeStatus(p.status_counts) || '-'})`)
    .join('; ');
  const sample = fetchErrorSample();
  const errorLine = sample ? ` Contoh error Fetch: ${plainText(sample)}.` : '';
  return buildResult(`Peringatan teknis: tidak ada platform dengan harga terbaca. Detail: ${detail}.${errorLine} Laporan AI tidak dikirim.`, null);
}

const usableRows = rows.filter((row) => healthyPlatforms.has(platformOf(row)));

const toAlert = (row) => ({
  nama_properti: row.nama_properti,
  platform: row.platform,
  target_date: String(row.target_date),
  room_type: row.room_type,
  previous_price: toPrice(row.previous_price),
  price: toPrice(row.price),
  delta_pct: toNumber(row.delta_pct),
  availability_status: row.availability_status,
  is_new: toBoolean(row.is_new),
});

const byLargestMove = (a, b) => Math.abs(b.delta_pct ?? 0) - Math.abs(a.delta_pct ?? 0);

const summarizeMarket = (marketRows) => [...marketRows
  .filter(hasPrice)
  .reduce((index, row) => {
    const key = requestKey(row);
    const price = toPrice(row.price);
    const current = index.get(key);
    if (!current || price < current.min_price) {
      index.set(key, {
        nama_properti: row.nama_properti,
        platform: row.platform,
        target_date: String(row.target_date),
        min_price: price,
        cheapest_room: row.room_type,
        price_basis: String(row.rate_key ?? '').split('|')[4] || 'unknown', // excl atau incl pajak
      });
    }
    return index;
  }, new Map())
  .values()]
  .sort((a, b) => a.target_date.localeCompare(b.target_date) || a.min_price - b.min_price);

// Stay yang terbaca dan SEMUA barisnya sold_out di platform itu (tiket.com "Semua kamar sudah penuh",
// Booking kamar tampil tanpa harga). Dikelompokkan per properti + platform supaya laporan ringkas.
const isSoldOut = (row) => String(row.availability_status ?? '').trim().toLowerCase() === 'sold_out';
const summarizeSoldOut = (stayRows) => {
  const rowsByStay = stayRows.reduce((index, row) => {
    const key = `${requestKey(row)}|${platformOf(row)}`;
    return index.set(key, [...(index.get(key) ?? []), row]);
  }, new Map());
  const soldOutStays = [...rowsByStay.values()].filter((rows) => rows.every(isSoldOut)).map((rows) => rows[0]);
  return [...soldOutStays
    .reduce((index, row) => {
      const key = `${row.nama_properti}|${row.platform}`;
      const entry = index.get(key) ?? { nama_properti: row.nama_properti, platform: row.platform, target_dates: [] };
      entry.target_dates = [...new Set([...entry.target_dates, String(row.target_date)])].sort();
      return index.set(key, entry);
    }, new Map())
    .values()]
    .slice(0, MAX_SOLD_OUT);
};

const comparedCount = usableRows.filter((row) => toPrice(row.previous_price) !== null).length;

const alerts = usableRows
  .filter((row) => toBoolean(row.is_alert) && hasPrice(row))
  .map(toAlert)
  .sort(byLargestMove)
  .slice(0, MAX_ALERTS);


// ---------- bagian tambahan report ----------
const roundPct = (value) => Math.round(value * 10) / 10;

// SALIN IDENTIK dari mesin pembanding. Dipakai same_room: "Deluxe Twin Bed" dan "Deluxe Twin Room" = kamar sama.
const ROOM_FILLER_WORDS = new Set(['room', 'rooms', 'kamar', 'bed', 'beds', 'with', 'dengan', 'the', 'a', 'and', 'dan']);
const canonicalRoom = (name) => (String(name ?? '').toLowerCase().match(/[a-z0-9]+/g) ?? [])
  .filter((token) => !ROOM_FILLER_WORDS.has(token))
  .sort()
  .join(' ');

// ---------- cross_platform ----------
const buildCrossPlatform = (market) => [...market
  .reduce((groups, row) => {
    const key = `${row.nama_properti}|${row.target_date}`;
    groups.set(key, [...(groups.get(key) ?? []), row]);
    return groups;
  }, new Map())
  .values()]
  .filter((rows) => new Set(rows.map((row) => row.platform)).size >= 2)
  .map((rows) => {
    const sorted = [...rows].sort((a, b) => a.min_price - b.min_price);
    const cheapest = sorted[0];
    const priciest = sorted[sorted.length - 1];
    return {
      nama_properti: cheapest.nama_properti,
      target_date: cheapest.target_date,
      prices: sorted.map((row) => ({ platform: row.platform, min_price: row.min_price, price_basis: row.price_basis })),
      same_basis: new Set(sorted.map((row) => row.price_basis)).size === 1, // false: satu harga termasuk pajak, lain belum
      cheapest_platform: cheapest.platform,
      spread_pct: roundPct(((priciest.min_price - cheapest.min_price) / cheapest.min_price) * 100),
    };
  });


// ---------- date_comparison ----------
const buildDateComparison = (market) => [...market
  .reduce((groups, row) => {
    const key = `${row.nama_properti}|${row.platform}`;
    groups.set(key, [...(groups.get(key) ?? []), row]);
    return groups;
  }, new Map())
  .values()]
  .filter((rows) => new Set(rows.map((row) => row.target_date)).size >= 2)
  .map((rows) => {
    const sorted = [...rows].sort((a, b) => a.min_price - b.min_price);
    const cheapest = sorted[0];
    const priciest = sorted[sorted.length - 1];
    return {
      nama_properti: cheapest.nama_properti,
      platform: cheapest.platform,
      prices: [...rows]
        .sort((a, b) => a.target_date.localeCompare(b.target_date))
        .map((row) => ({ target_date: row.target_date, min_price: row.min_price, cheapest_room: row.cheapest_room, price_basis: row.price_basis })),
      same_room: new Set(rows.map((row) => canonicalRoom(row.cheapest_room))).size === 1, // false: kamar termurah beda antar tanggal
      cheapest_date: cheapest.target_date,
      priciest_date: priciest.target_date,
      spread_pct: roundPct(((priciest.min_price - cheapest.min_price) / cheapest.min_price) * 100),
      same_basis: new Set(rows.map((row) => row.price_basis)).size === 1,
    };
  })
  .sort((a, b) => b.spread_pct - a.spread_pct);

// ---------- trends ----------
// Histori sheet + baris run ini (timestamp sekarang). Baris run ini belum punya timestamp di sheet.
const readHistory = () => [
  ...$(HISTORY_NODE).all().map((item) => item.json).filter((row) => row.rate_key),
  ...rows.map((row) => ({ ...row, timestamp: $now.toISO() })),
];

const lastPricePerDay = (rows) => [...rows
  .sort((a, b) => String(a.timestamp).localeCompare(String(b.timestamp)))
  .reduce((days, row) => days.set(String(row.timestamp).slice(0, 10), row), new Map())
  .entries()]
  .map(([day, row]) => ({ day, row, price: toPrice(row.price) }));

const streakAtEnd = (series) => {
  let direction = 0;
  let days = 0;
  for (let i = series.length - 1; i > 0; i--) {
    const step = Math.sign(series[i].price - series[i - 1].price);
    if (step === 0 || (direction !== 0 && step !== direction)) break;
    direction = step;
    days++;
  }
  return { direction, days };
};

const buildTrends = (history, targetDates) => [...history
  .filter((row) => row.rate_key && toPrice(row.price) !== null && targetDates.has(String(row.target_date)))
  .reduce((groups, row) => groups.set(row.rate_key, [...(groups.get(row.rate_key) ?? []), row]), new Map())
  .values()]
  .map((rows) => {
    const series = lastPricePerDay(rows);
    const { direction, days } = streakAtEnd(series);
    const first = series[series.length - 1 - days];
    const last = series[series.length - 1];
    return { direction, days, first, last };
  })
  .filter((trend) => trend.days >= MIN_STREAK_DAYS)
  .map(({ direction, days, first, last }) => ({
    nama_properti: last.row.nama_properti,
    platform: last.row.platform,
    target_date: String(last.row.target_date),
    room_type: last.row.room_type,
    direction: direction > 0 ? 'naik' : 'turun',
    days,
    from_price: first.price,
    to_price: last.price,
    change_pct: roundPct(((last.price - first.price) / first.price) * 100),
  }))
  .sort((a, b) => b.days - a.days || Math.abs(b.change_pct) - Math.abs(a.change_pct))
  .slice(0, MAX_TRENDS);


const report = {
  diagnostics: { fetch_error_sample: fetchErrorSample() },
  run: {
    target_dates: [...new Set(usableRows.map((row) => String(row.target_date)))].sort(),
    rates_total: usableRows.length,
    rates_compared: comparedCount,
    // baseline: belum ada satu pun harga pembanding (sheet kosong atau semua tanggal baru)
    mode: comparedCount === 0 ? 'baseline' : 'tracking',
  },
  platform_health: {
    healthy: platformHealth.filter((p) => p.healthy),
    failed: failedPlatforms,
  },
  alerts,
  market: summarizeMarket(usableRows),
  sold_out: summarizeSoldOut(usableRows),
};
const targetDates = new Set(report.run.target_dates);

return buildResult(null, {
  ...report,
  cross_platform: buildCrossPlatform(report.market),
  date_comparison: buildDateComparison(report.market),
  trends: buildTrends(readHistory(), targetDates),
});

// Node: Prepare Gemini Batches (v23, gabungan Trim Markdown + Build Batches)
// Posisi: Loop Markdown Pages (done) -> [node ini] -> Gemini Extract Rooms
// Mode: Run Once for All Items
//
// 1. Potong markdown tiap halaman: simpan baris harga Rupiah plus beberapa baris di atasnya (nama kamar, sarapan).
// 2. Kelompokkan halaman berharga ke batch. 1 item output = 1 request Gemini (hemat kuota free tier).
// Halaman tanpa teks harga (fetch gagal, kamar penuh, tanpa Rp) TIDAK dikirim ke Gemini. Diagnosisnya ikut
// di field pages, dibaca Normalize Markdown Rates.
//
// Request dipasangkan lewat URUTAN: output done dari loop menjaga urutan item. Jumlah dicek supaya pasangan
// tidak bergeser diam-diam.

const REQUEST_NODE = 'Build Requests';
const MARKDOWN_PATH = 'markdown';
const BATCH_SIZE = 10;            // halaman per request Gemini
const MAX_CHARS = 6000;           // per halaman
const CONTEXT_LINES_BEFORE = 6;
const PRICE_LINE = /(rp|idr)\s?[\d.,]{4,}/i;

// Pengumuman kamar penuh (properti penuh atau tutup sementara). Halaman tanpa baris harga, tapi TERBACA.
// Bukti: tiket.com Dago 207, 09 Oct 2026: "Semua kamar sudah penuh" (kode 404-bCwDjZ).
// Hanya dipakai kalau halaman tanpa baris harga, supaya teks yang sama di bagian lain halaman tidak salah baca.
const SOLD_OUT_NOTICES = [/semua kamar sudah penuh/i];

const cleanMarkdown = (markdown) => String(markdown ?? '')
  .replace(/!\[[^\]]*\]\([^)]*\)/g, '')
  .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
  .replace(/data:[^\s)]+/g, '')
  .replace(/https?:\/\/\S+/g, '')
  .replace(/[ \t]+/g, ' ');

const excerptAroundPrices = (lines) => {
  const keep = new Set();
  lines.forEach((line, index) => {
    if (PRICE_LINE.test(line)) {
      for (let j = Math.max(0, index - CONTEXT_LINES_BEFORE); j <= index; j++) keep.add(j);
    }
  });
  return [...keep].sort((a, b) => a - b).map((i) => lines[i]).join('\n').slice(0, MAX_CHARS);
};

const errorText = (error) => (error && typeof error === 'object' ? (error.message ?? JSON.stringify(error)) : error);

// fetch_error, sold_out_notice, no_price_text: penyebab halaman tidak dikirim ke Gemini
const diagnoseUnsent = (page) => {
  if (page.fetch_error) return 'fetch_failed';
  if (page.has_sold_out_notice) return 'sold_out_notice';
  return 'no_price_text';
};

const requests = $(REQUEST_NODE).all()
  .map((item) => item.json)
  .filter((request) => request.extraction_path === MARKDOWN_PATH);
const fetched = $input.all().map((item) => item.json);
if (fetched.length !== requests.length) {
  throw new Error(`Jumlah halaman (${fetched.length}) beda dengan jumlah request markdown (${requests.length}). Pasangan per urutan tidak valid.`);
}

const pages = fetched.map((page, index) => {
  const lines = cleanMarkdown(page.markdown).split('\n').map((line) => line.trim()).filter(Boolean);
  const excerpt = excerptAroundPrices(lines);
  const summary = {
    page_id: `p${index + 1}`,
    request: requests[index],
    fetch_error: page.error ? String(errorText(page.error)) : null,
    has_sold_out_notice: excerpt.length === 0 && SOLD_OUT_NOTICES.some((pattern) => lines.some((line) => pattern.test(line))),
  };
  return { ...summary, excerpt, unsent_diagnosis: excerpt.length > 0 ? null : diagnoseUnsent(summary) };
});

// Ringkasan halaman TANPA potongan teks, supaya item batch tetap kecil
const pageSummaries = pages.map(({ excerpt, ...summary }) => summary);
const pricedPages = pages.filter((page) => page.excerpt.length > 0);

const batches = [];
for (let start = 0; start < pricedPages.length; start += BATCH_SIZE) {
  const chunk = pricedPages.slice(start, start + BATCH_SIZE);
  batches.push({
    page_ids: chunk.map((page) => page.page_id),
    pages_text: chunk.map((page) => `=== PAGE ${page.page_id} ===\n${page.excerpt}`).join('\n\n'),
  });
}

// Minimal 1 item supaya alur tetap sampai ke laporan walau semua halaman tanpa harga.
// Item kosong ini tetap memanggil Gemini 1 kali. Kasus ini jarang (semua halaman gagal atau penuh).
const outputBatches = batches.length > 0 ? batches : [{ page_ids: [], pages_text: '' }];

return outputBatches.map((batch) => ({ json: { ...batch, pages: pageSummaries } }));

// Node: Normalize Markdown Rates (v23, gabungan Parse Batch + Normalize Batch + Calculate Delta Batch)
// Posisi: Gemini Extract Rooms -> [node ini] -> Merge Rates (input 2)
// Mode: Run Once for All Items
//
// 1. Petakan balasan Gemini ke halaman (page_id dari Prepare Gemini Batches).
// 2. Ubah ke 1 baris per rate. Minimal 1 baris per halaman, termasuk halaman gagal.
// 3. Bandingkan dengan histori (mesin pembanding sama dengan Normalize Booking Rates).
// extraction_status saat halaman tanpa kamar:
//   fetch_failed     MrScraper Fetch Markdown error
//   no_price_text    markdown terambil, tanpa baris Rp/IDR
//   sold_out_notice  halaman terbaca, ada pengumuman semua kamar penuh
//   llm_failed       request Gemini gagal (kuota, 503)
//   llm_bad_json     Gemini membalas, bukan JSON valid
//   no_room_types    Gemini membalas JSON valid, halaman ini tanpa kamar

const BATCH_NODE = 'Prepare Gemini Batches';

const stripFences = (text) => String(text ?? '')
  .replace(/^\s*```(?:json)?/i, '')
  .replace(/```\s*$/, '')
  .trim();

const parsePages = (text) => {
  try {
    const parsed = JSON.parse(stripFences(text));
    return Array.isArray(parsed?.pages) ? parsed.pages : null;
  } catch (error) {
    return null;
  }
};

// Gemini dengan thinking bisa mengirim beberapa part. Gabung part teks yang bukan "thought".
const replyText = (reply) => {
  const parts = (reply.content?.parts ?? []).filter((part) => typeof part?.text === 'string' && !part.thought);
  return parts.length > 0 ? parts.map((part) => part.text).join('\n') : undefined;
};

// Gemini Extract Rooms memakai On Error: Continue (regular output), jadi 1 balasan per batch, urutan sama
const replies = $input.all().map((item) => item.json);
const batches = $(BATCH_NODE).all().map((item) => item.json);
const pages = batches[0]?.pages ?? [];

// page_id -> { room_types, diagnosis } dari tiap batch yang dikirim ke Gemini
const resultByPage = new Map();
batches.forEach((batch, index) => {
  const reply = replies[index] ?? {};
  const text = reply.error ? undefined : replyText(reply);
  const parsedPages = text === undefined ? null : parsePages(text);
  const failure = text === undefined ? 'llm_failed' : 'llm_bad_json';
  const roomsByPage = new Map((parsedPages ?? []).map((page) => [page?.page_id, page?.room_types]));
  (batch.page_ids ?? []).forEach((pageId) => {
    const rooms = roomsByPage.get(pageId);
    resultByPage.set(pageId, parsedPages === null
      ? { room_types: [], diagnosis: failure }
      : { room_types: Array.isArray(rooms) ? rooms : [], diagnosis: 'no_room_types' });
  });
});

const EXTRACTION_STATUS = {
  OK: 'ok',
  NO_PRICES: 'no_prices',
  NO_ROOM_TYPES: 'no_room_types',
  WRONG_CURRENCY: 'wrong_currency',
  SOLD_OUT_NOTICE: 'sold_out_notice', // pengumuman kamar penuh di halaman (Trim Markdown)
};

// Status yang berarti halaman terbaca dan kamar memang habis
const SOLD_OUT_STATUSES = new Set([EXTRACTION_STATUS.NO_PRICES, EXTRACTION_STATUS.SOLD_OUT_NOTICE]);

const parsePrice = (value) => {
  const match = String(value ?? '').match(/\d[\d.,]*/);
  if (!match) {
    return null;
  }
  const digits = match[0].replace(/[.,]\d{1,2}$/, '').replace(/\D/g, '');
  return digits ? Number.parseInt(digits, 10) : null;
};

const isRupiah = (value) => /rp|idr/i.test(String(value ?? ''));

const baseRowOf = (request) => ({
  listing_id: request.listing_id,
  nama_properti: request.nama_properti,
  platform: request.platform,
  target_date: request.target_date,
});

const toRateRow = (base, roomName, rate) => {
  const rupiah = isRupiah(rate.price_total);
  const price = rupiah ? parsePrice(rate.price_total) : null;
  return {
    ...base,
    room_type: roomName,
    price,
    availability_status: price === null ? 'unknown' : 'available',
    breakfast_included: Boolean(rate.breakfast_included),
    cancellation_policy: rate.cancellation_policy || 'not_available',
    price_basis: 'excl', // prompt Gemini meminta harga sebelum pajak
    extraction_status: rupiah ? EXTRACTION_STATUS.OK : EXTRACTION_STATUS.WRONG_CURRENCY,
  };
};

const toUnavailableRow = (base, roomName, status) => ({
  ...base,
  room_type: roomName,
  price: null,
  // sold_out HANYA kalau halaman terbaca dan kamar habis (no_prices, sold_out_notice).
  // Status lain = kegagalan scraping, bukan kamar habis.
  availability_status: SOLD_OUT_STATUSES.has(status) ? 'sold_out' : 'unknown',
  breakfast_included: false,
  cancellation_policy: 'not_available',
  extraction_status: status,
});

const toRows = ({ request, room_types: roomTypes, diagnosis }) => {
  const base = baseRowOf(request);
  if (roomTypes.length === 0) {
    const status = diagnosis ?? EXTRACTION_STATUS.NO_ROOM_TYPES;
    const label = status === EXTRACTION_STATUS.SOLD_OUT_NOTICE ? 'All rooms sold out' : 'No room type returned';
    return [toUnavailableRow(base, label, status)];
  }
  return roomTypes.flatMap((room) => {
    const roomName = room.name || 'Unknown room type';
    const rates = Array.isArray(room.prices) ? room.prices : [];
    return rates.length === 0
      ? [toUnavailableRow(base, roomName, EXTRACTION_STATUS.NO_PRICES)]
      : rates.map((rate) => toRateRow(base, roomName, rate));
  });
};

const normalizedRows = pages.flatMap((page) => {
  const result = resultByPage.get(page.page_id) ?? { room_types: [], diagnosis: page.unsent_diagnosis ?? 'no_price_text' };
  return toRows({ request: page.request, ...result });
});

// ===== MESIN PEMBANDING (SALIN IDENTIK di Normalize Booking Rates dan Normalize Markdown Rates) =====
// Code node tidak bisa berbagi modul. Ubah aturan alert di KEDUA node.
//
// Aturan alert: alert = LEVEL harga baru yang terkonfirmasi di 2 scan berturut-turut, berbeda >= 5%
// dari level lama. Alasan: MrScraper AI mengambil rate plan berbeda antar scan. Contoh Girava 09 Oct:
// 869.760, 1.234.691, 869.760 (3 scan). Satu scan yang menyimpang hanya menjadi kandidat.
// Konsekuensi: alert muncul 1 scan setelah perubahan pertama terlihat.
// Kunci pembanding: listing|tanggal|kamar kanonik|sarapan. Basis pajak tidak masuk kunci karena
// harga dinormalisasi ke excl. rate_key yang ditulis ke sheet tetap format lama (nama asli + basis).

const HISTORY_NODE = 'Get Rate History';
const ALERT_THRESHOLD_PCT = 5;  // selisih level lama ke level baru
const SAME_LEVEL_PCT = 2.5;     // selisih sekecil ini = level sama. Fluktuasi Tiket antar scan sampai 2,4%

// Harga incl = excl x 1,0901. Bukti: 60 dari 71 pergantian basis Booking (run 100 sampai 109) cocok faktor ini.
// Teks "10% tax" dari MrScraper tidak dipakai karena tidak cocok dengan data.
// unknown diperlakukan incl: 28 dari 35 kasus unknown setara harga incl.
const INCL_TAX_FACTOR = 1.0901;
const BASIS_FACTOR = { excl: 1, incl: INCL_TAX_FACTOR, unknown: INCL_TAX_FACTOR };

const normalizeKeyPart = (value) => String(value ?? '').trim().toLowerCase();

// 1 definisi key untuk tulis dan baca. Tidak bergantung ke format tanggal/boolean di Sheets.
const buildRateKey = (row) => [
  row.listing_id,
  row.target_date,
  row.room_type,
  row.breakfast_included,
  row.price_basis ?? 'unknown',
].map(normalizeKeyPart).join('|');

// Kata yang tidak membedakan tipe kamar. Token diurutkan supaya urutan kata tidak berpengaruh.
// "Deluxe Room Twin Bed" dan "Deluxe Twin Room" -> "deluxe twin".
// SALIN IDENTIK di Calculate Delta, Calculate Delta Batch, dan Enrich Report (Code node tidak bisa berbagi modul).
const ROOM_FILLER_WORDS = new Set(['room', 'rooms', 'kamar', 'bed', 'beds', 'with', 'dengan', 'the', 'a', 'and', 'dan']);
const canonicalRoom = (name) => (String(name ?? '').toLowerCase().match(/[a-z0-9]+/g) ?? [])
  .filter((token) => !ROOM_FILLER_WORDS.has(token))
  .sort()
  .join(' ');

const toCompareKey = (rateKey) => {
  const [listing, date, room, breakfast] = String(rateKey).split('|');
  return [listing, date, canonicalRoom(room), breakfast].join('|');
};
const basisOf = (rateKey) => String(rateKey).split('|')[4] || 'unknown';
const factorOf = (basis) => BASIS_FACTOR[basis] ?? INCL_TAX_FACTOR;
const toExcl = (price, basis) => price / factorOf(basis);
const fromExcl = (priceExcl, basis) => Math.round(priceExcl * factorOf(basis));

// Harga selalu integer IDR. Buang semua non-digit supaya aman dari format "500.000" atau "500,000".
const toPrice = (value) => {
  const match = String(value ?? '').match(/\d[\d.,]*/);
  if (!match) {
    return null;
  }
  const digits = match[0].replace(/[.,]\d{1,2}$/, '').replace(/\D/g, '');
  return digits ? Number(digits) : null;
};

const pctChange = (current, reference) => Math.round(((current - reference) / reference) * 1000) / 10;
const isSameLevel = (price, level) => Math.abs(pctChange(price, level)) <= SAME_LEVEL_PCT;
const byNewestFirst = (a, b) => new Date(b.timestamp) - new Date(a.timestamp);

// ---------- histori ----------
// Pengaman: baris dengan run_id run ini bukan histori
const currentRunId = (() => {
  try {
    return String($execution.id);
  } catch (notAvailable) {
    return '';
  }
})();

const historyRows = $(HISTORY_NODE).all()
  .map((item) => item.json)
  .filter((row) => row.rate_key && String(row.run_id) !== currentRunId);

// Urutan run menurut waktu baris pertama
const runStartedAt = historyRows.reduce((index, row) => {
  const time = new Date(row.timestamp).getTime();
  return index.set(row.run_id, Math.min(index.get(row.run_id) ?? Infinity, time));
}, new Map());

// compareKey -> Map(run_id -> observasi termurah di run itu). Satu observasi per scan.
// Observasi = { excl, price, basis }. Harga asli disimpan supaya previous_price tidak bergeser karena pembulatan.
const observationsByKey = historyRows.reduce((index, row) => {
  const price = toPrice(row.price);
  if (price === null) {
    return index;
  }
  const key = toCompareKey(row.rate_key);
  const perRun = index.get(key) ?? new Map();
  const basis = basisOf(row.rate_key);
  const observation = { excl: toExcl(price, basis), price, basis };
  const cheapest = perRun.get(row.run_id);
  if (!cheapest || observation.excl < cheapest.excl) {
    perRun.set(row.run_id, observation);
  }
  return index.set(key, perRun);
}, new Map());

const seriesOf = (key) => [...(observationsByKey.get(key) ?? new Map())]
  .sort(([runA], [runB]) => runStartedAt.get(runA) - runStartedAt.get(runB))
  .map(([, observation]) => observation);

// Baris terbaru per rate_key persis. Dipakai untuk baris yang bukan termurah di kuncinya.
const latestByRateKey = [...historyRows]
  .sort(byNewestFirst)
  .reduce((index, row) => (index.has(row.rate_key) ? index : index.set(row.rate_key, row)), new Map());

// Status terakhir yang diketahui per kunci pembanding (available, sold_out)
const lastKnownStatus = [...historyRows]
  .sort(byNewestFirst)
  .filter((row) => normalizeKeyPart(row.availability_status) !== 'unknown')
  .reduce((index, row) => {
    const key = toCompareKey(row.rate_key);
    return index.has(key) ? index : index.set(key, normalizeKeyPart(row.availability_status));
  }, new Map());

// Stay dianggap sudah dipantau hanya kalau halamannya pernah TERBACA (bukan fetch_failed, empty_response, dst)
const READ_STATUSES = new Set(['ok', 'no_prices', 'wrong_currency', 'sold_out_notice']);
const stayOf = (rateKey) => String(rateKey).split('|').slice(0, 2).join('|');
const seenStays = new Set(historyRows
  .filter((row) => READ_STATUSES.has(normalizeKeyPart(row.extraction_status)))
  .map((row) => stayOf(row.rate_key)));
const seenKeys = new Set(historyRows.map((row) => toCompareKey(row.rate_key)));

// ---------- level harga ----------
// Level terkonfirmasi = harga yang muncul di 2 scan berturut-turut (selisih <= SAME_LEVEL_PCT).
// Harga yang beda dari level hanya menjadi kandidat sampai scan berikutnya mengulanginya.
// Level menyimpan harga asli terakhir per basis. Contoh Dago 207: 293.554 (excl) dan 320.000 (incl) = level sama.
const toLevel = (observation, previousLevel = null) => ({
  excl: observation.excl,
  priceByBasis: { ...(previousLevel?.priceByBasis ?? {}), [observation.basis]: observation.price },
});

const replayLevels = (series) => series.reduce(({ confirmed, candidate }, observation) => {
  if (confirmed !== null && isSameLevel(observation.excl, confirmed.excl)) {
    return { confirmed: toLevel(observation, confirmed), candidate: null };
  }
  if (candidate !== null && isSameLevel(observation.excl, candidate.excl)) {
    return { confirmed: toLevel(observation, toLevel(candidate)), candidate: null };
  }
  return { confirmed, candidate: observation };
}, { confirmed: null, candidate: null });

// reference = observasi pembanding. levelChanged = scan ini mengonfirmasi level baru.
const assessLevel = (series, priceExcl) => {
  const { confirmed, candidate } = replayLevels(series);
  if (confirmed !== null && isSameLevel(priceExcl, confirmed.excl)) {
    return { reference: confirmed, levelChanged: false };
  }
  if (candidate !== null && isSameLevel(priceExcl, candidate.excl)) {
    // Tanpa level lama (stay baru dipantau) = konfirmasi level pertama, bukan perubahan
    return { reference: confirmed ?? candidate, levelChanged: confirmed !== null };
  }
  return { reference: confirmed ?? candidate, levelChanged: false };
};

// previous_price ditulis dalam basis baris ini supaya setara dengan price.
// Pakai harga asli kalau level pernah teramati di basis yang sama, konversi faktor kalau belum.
const referencePriceIn = (reference, basis) => reference.priceByBasis?.[basis]
  ?? (reference.basis === basis ? reference.price : fromExcl(reference.excl, basis));

// ---------- run ini ----------
// Satu tipe kamar bisa punya beberapa opsi harga dengan status sarapan sama (beda okupansi atau promo).
// Ambil harga termurah per rate_key, sama seperti v21.
const isCheaper = (candidate, current) => {
  const candidatePrice = toPrice(candidate.price);
  const currentPrice = toPrice(current.price);
  if (candidatePrice === null) return false;
  return currentPrice === null || candidatePrice < currentPrice;
};

const cheapestPerRateKey = (rows) => [...rows
  .reduce((index, row) => {
    const key = buildRateKey(row);
    const current = index.get(key);
    return !current || isCheaper(row, current) ? index.set(key, row) : index;
  }, new Map())
  .values()];

// ---------- pembanding ----------
// Input: baris ternormalisasi (1 item per rate). Output: baris + rate_key, previous_price, delta_pct,
// is_new, status_changed, is_alert. Semua baris dikembalikan, termasuk baris gagal (untuk diagnosis).
const compareWithHistory = (normalizedRows) => {
  const currentRows = cheapestPerRateKey(normalizedRows)
    .map((row) => {
      const rateKey = buildRateKey(row);
      const price = toPrice(row.price);
      const basis = basisOf(rateKey);
      return { row, rateKey, compareKey: toCompareKey(rateKey), basis, price, priceExcl: price === null ? null : toExcl(price, basis) };
    });

  // Baris termurah per kunci pembanding = wakil kunci itu di scan ini. Hanya wakil yang bisa memicu alert.
  const leadByKey = currentRows
    .filter((entry) => entry.priceExcl !== null)
    .reduce((index, entry) => {
      const lead = index.get(entry.compareKey);
      return !lead || entry.priceExcl < lead.priceExcl ? index.set(entry.compareKey, entry) : index;
    }, new Map());

  const statusChangedOf = (entry) => {
    const current = normalizeKeyPart(entry.row.availability_status);
    const previous = lastKnownStatus.get(entry.compareKey);
    return current !== 'unknown' && previous !== undefined && current !== previous;
  };

  const evaluate = (entry) => {
    const base = {
      ...entry.row,
      rate_key: entry.rateKey,
      is_new: !seenKeys.has(entry.compareKey) && seenStays.has(stayOf(entry.rateKey)),
      status_changed: statusChangedOf(entry),
      is_alert: false,
    };

    if (entry.priceExcl === null) {
      return { ...base, previous_price: null, delta_pct: null };
    }

    if (leadByKey.get(entry.compareKey) === entry) {
      const series = seriesOf(entry.compareKey);
      const { reference, levelChanged } = assessLevel(series, entry.priceExcl);
      if (reference === null) {
        return { ...base, previous_price: null, delta_pct: null };
      }
      const deltaPct = pctChange(entry.priceExcl, reference.excl);
      return {
        ...base,
        previous_price: referencePriceIn(reference, entry.basis),
        delta_pct: deltaPct,
        is_alert: levelChanged && Math.abs(deltaPct) >= ALERT_THRESHOLD_PCT,
      };
    }

    // Opsi lebih mahal dengan kunci sama: pembanding = rate_key persis, hanya informasi
    const previousPrice = toPrice(latestByRateKey.get(entry.rateKey)?.price);
    return {
      ...base,
      previous_price: previousPrice,
      delta_pct: previousPrice ? pctChange(entry.price, previousPrice) : null,
    };
  };

  return currentRows.map(evaluate);
};

return compareWithHistory(normalizedRows).map((json) => ({ json }));

// Node: Compose Telegram Message (v23, gabungan Format Telegram HTML + Fallback Report + Format Telegram HTML2)
// Posisi: Merge Watchlist and Area -> [node ini] -> Send Telegram Report
// Mode: Run Once for All Items
//
// 1 run = 1 pesan Telegram berisi 2 bagian:
//   Watchlist  teks Gemini Write Report. Kalau Gemini gagal (kuota, 503): ringkasan otomatis dari report.
//              Kalau tidak ada platform sehat: pesan warning dari Build Report.
//   Area scan  ringkasan deterministik dari Append Area_Scan, atau alasan Listing Agent tidak menemukan listing.
// Telegram node: Text = {{ $json.telegram_html }}, Parse Mode = HTML, Append n8n Attribution = OFF.

const TELEGRAM_TEXT_LIMIT = 4096;
const TRUNCATION_NOTE = '\n\n(pesan dipotong, lihat sheet untuk detail)';
const MAX_AREA_LISTINGS = 5;

// ---------- utilitas ----------
const escapeHtml = (text) => String(text ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const rupiah = (value) => `Rp${Number(value).toLocaleString('id-ID')}`;
const pct = (value) => `${value > 0 ? '+' : ''}${String(value).replace('.', ',')}%`; // format persen Indonesia
const bold = (text) => `<b>${escapeHtml(text)}</b>`;
const line = (text) => escapeHtml(text);

// Node yang tidak jalan di run ini (cabang lain dari If) melempar error saat dibaca
const readNode = (name) => {
  try {
    return $(name).all().map((item) => item.json);
  } catch (notExecuted) {
    return null;
  }
};

// Potong per code point supaya emoji (surrogate pair) tidak terbelah
const truncate = (text, maxLength) => {
  if (text.length <= maxLength) {
    return text;
  }
  let result = '';
  for (const char of text) {
    if (result.length + char.length > maxLength - TRUNCATION_NOTE.length) {
      break;
    }
    result += char;
  }
  return result + TRUNCATION_NOTE;
};

const stripAsterisks = (text) => text.replace(/\*\*/g, '');

// Urutan penting: escape dulu, baru ubah markdown jadi tag HTML
const markdownToTelegramHtml = (text) => escapeHtml(text)
  .replace(/^#{1,6}\s*(.+)$/gm, (_, title) => `<b>${stripAsterisks(title)}</b>`)
  .replace(/\*\*([^*\n]+?)\*\*/g, '<b>$1</b>')
  .replace(/`([^`\n]+?)`/g, '<code>$1</code>')
  .replace(/^(\s*)[*-]\s+/gm, '$1• ')
  .replace(/\*/g, '')
  .replace(/^\s*-{3,}\s*$/gm, '')
  .replace(/\n{3,}/g, '\n\n');

// ---------- bagian watchlist ----------
// Gemini dengan thinking bisa mengirim beberapa part. Gabung part teks yang bukan "thought".
const geminiText = (reply) => (reply?.content?.parts ?? [])
  .filter((part) => typeof part?.text === 'string' && !part.thought)
  .map((part) => part.text)
  .join('\n')
  .trim();

const fallbackLines = (report) => {
  const alertLines = (report.alerts ?? [])
    .filter((alert) => alert.delta_pct !== null)
    .slice(0, 3)
    .map((alert) => line(`• ${alert.nama_properti} (${alert.platform}, ${alert.target_date}, ${alert.room_type}): `
      + `${rupiah(alert.previous_price)} ke ${rupiah(alert.price)} (${pct(alert.delta_pct)})`));

  const marketByDate = (report.market ?? []).reduce((index, row) => {
    (index[row.target_date] ??= []).push(row);
    return index;
  }, {});
  const marketLines = Object.entries(marketByDate).map(([date, rows]) => {
    const sorted = [...rows].sort((a, b) => a.min_price - b.min_price);
    const low = sorted[0];
    const high = sorted[sorted.length - 1];
    return sorted.length === 1
      ? line(`• ${date}: hanya ${low.nama_properti} ${rupiah(low.min_price)}`)
      : line(`• ${date}: termurah ${low.nama_properti} ${rupiah(low.min_price)}, tertinggi ${high.nama_properti} ${rupiah(high.min_price)}`);
  });

  const crossPlatformLines = (report.cross_platform ?? []).slice(0, 2)
    .map((row) => line(`• ${row.nama_properti} (${row.target_date}): termurah di ${row.cheapest_platform}, selisih ${pct(row.spread_pct).replace('+', '')}`
      + (row.same_basis ? '' : ' (sebagian karena pajak)')));

  const dateLines = (report.date_comparison ?? []).slice(0, 3)
    .map((row) => line(`• ${row.nama_properti} (${row.platform}): termurah ${row.cheapest_date}, termahal ${row.priciest_date}, selisih ${pct(row.spread_pct).replace('+', '')}`
      + (row.same_room ? '' : ' (kamar termurah berbeda)')));

  const soldOutLines = (report.sold_out ?? []).slice(0, 3)
    .map((row) => line(`• ${row.nama_properti} (${row.platform}): semua kamar penuh ${row.target_dates.join(', ')}`));

  const section = (title, lines) => (lines.length ? ['', bold(title), ...lines] : []);
  const failed = (report.platform_health?.failed ?? []).map((p) => p.platform);

  return [
    `${bold('Laporan rate kompetitor')} (ringkasan otomatis, analisis AI sedang tidak tersedia)`,
    '',
    bold('Perubahan harga terkonfirmasi'),
    ...(report.run?.mode === 'baseline'
      ? [line('• Scan dasar: belum ada harga pembanding. Delta muncul mulai scan berikutnya')]
      : (alertLines.length ? alertLines : [line('• Tidak ada perubahan harga terkonfirmasi')])),
    '',
    bold('Pasar (harga kamar termurah tiap listing)'),
    ...marketLines,
    ...section('Antar platform', crossPlatformLines),
    ...section('Antar tanggal menginap', dateLines),
    ...section('Kamar penuh', soldOutLines),
    ...(failed.length ? ['', line(`Platform tidak ikut dianalisis: ${failed.join(', ')}`)] : []),
  ];
};

// Potong SEBELUM ubah ke HTML supaya tag tidak terbelah. Escape bisa menambah panjang, jadi budget diturunkan bertahap.
const BUDGET_STEP = 300;
const fitMarkdown = (text, budget) => {
  for (let rawBudget = budget; rawBudget >= BUDGET_STEP; rawBudget -= BUDGET_STEP) {
    const html = markdownToTelegramHtml(truncate(text, rawBudget));
    if (html.length <= budget) {
      return html;
    }
  }
  return line(truncate(text, BUDGET_STEP));
};

// Baris HTML utuh dibuang dari belakang sampai muat
const fitLines = (lines, budget) => {
  const kept = [...lines];
  while (kept.length > 1 && kept.join('\n').length + TRUNCATION_NOTE.length > budget) {
    kept.pop();
  }
  const text = kept.join('\n');
  return kept.length < lines.length ? text + escapeHtml(TRUNCATION_NOTE) : text;
};

const watchlistSection = (budget) => {
  const built = readNode('Build Report')?.[0];
  if (!built) {
    return line('Watchlist: tidak ada data (cabang watchlist tidak jalan).');
  }
  if (built.is_data_quality_issue) {
    return line(built.warning_message);
  }
  const text = geminiText(readNode('Gemini Write Report')?.[0]);
  return text ? fitMarkdown(text, budget) : fitLines(fallbackLines(built.report), budget);
};

// ---------- bagian area scan ----------
const toPrice = (value) => {
  const digits = String(value ?? '').replace(/[.,]\d{1,2}$/, '').replace(/\D/g, '');
  return digits ? Number(digits) : null;
};
const readParam = (url, name) => String(url ?? '').match(new RegExp(`[?&]${name}=([^&#]+)`))?.[1] ?? null;

const areaSection = () => {
  const city = readNode('Build Area Scan URL')?.[0]?.area_city ?? 'area';
  const rows = readNode('Append Area_Scan');
  if (!rows) {
    const marker = readNode('Split Listings')?.[0];
    const reason = marker?.no_listing_reason ?? 'cabang area tidak jalan';
    return [bold(`Area scan ${city}`), line(`• Listing Agent tidak menghasilkan listing. Alasan: ${reason}`)].join('\n');
  }
  const priced = rows
    .map((row) => ({ name: row.nama_properti, price: toPrice(row.price_per_night), rating: row.rating }))
    .filter((row) => row.price !== null && row.price > 0)
    .sort((a, b) => a.price - b.price);
  const checkin = readParam(rows[0]?.detail_url, 'checkin');
  const header = bold(`Area scan ${city} (Booking.com${checkin ? `, check-in ${checkin}` : ''})`);
  if (priced.length === 0) {
    return [header, line(`• ${rows.length} properti terbaca, harga tidak terbaca`)].join('\n');
  }
  const average = Math.round(priced.reduce((sum, row) => sum + row.price, 0) / priced.length);
  return [
    header,
    line(`• ${priced.length} properti. Rata-rata ${rupiah(average)}, termurah ${priced[0].name} ${rupiah(priced[0].price)}, `
      + `termahal ${priced[priced.length - 1].name} ${rupiah(priced[priced.length - 1].price)}`),
    ...priced.slice(0, MAX_AREA_LISTINGS).map((row, index) => line(`${index + 1}. ${row.name}: ${rupiah(row.price)}${row.rating ? ` (rating ${row.rating})` : ''}`)),
  ].join('\n');
};

// ---------- pesan ----------
// Bagian area pendek dan tetap utuh. Bagian watchlist dipotong kalau total melewati batas Telegram.
const area = areaSection();
const watchlist = watchlistSection(TELEGRAM_TEXT_LIMIT - area.length - 2);

return [{ json: { telegram_html: `${watchlist}\n\n${area}` } }];
